package.json.text:
{
	"name": "get-tsconfig",
	"version": "0.0.0-semantic-release",
	"description": "Find and parse the tsconfig.json file from a directory path",
	"keywords": [
		"get-tsconfig",
		"get",
		"typescript",
		"tsconfig",
		"tsconfig.json"
	],
	"license": "MIT",
	"repository": "privatenumber/get-tsconfig",
	"funding": "https://github.com/privatenumber/get-tsconfig?sponsor=1",
	"author": {
		"name": "Hiroki Osame",
		"email": "hiroki.osame@gmail.com"
	},
	"files": [
		"dist"
	],
	"type": "module",
	"main": "./dist/index.cjs",
	"module": "./dist/index.mjs",
	"types": "./dist/index.d.cts",
	"exports": {
		"require": {
			"types": "./dist/index.d.cts",
			"default": "./dist/index.cjs"
		},
		"import": {
			"types": "./dist/index.d.mts",
			"default": "./dist/index.mjs"
		}
	},
	"imports": {
		"#get-tsconfig": {
			"types": "./src/index.ts",
			"development": "./src/index.ts",
			"default": "./dist/index.mjs"
		}
	},
	"packageManager": "pnpm@10.19.0",
	"scripts": {
		"lint": "lintroll --cache --node --ignore-pattern tests/fixtures . --allow-abbreviation=dir",
		"build": "pkgroll --minify --target node12.20",
		"test": "tsx tests",
		"dev": "tsx watch --conditions=development tests",
		"type-check": "tsc --noEmit",
		"prepack": "pnpm build && clean-pkg-json"
	},
	"dependencies": {
		"resolve-pkg-maps": "^1.0.0"
	},
	"devDependencies": {
		"@types/node": "^24.10.4",
		"@yarnpkg/pnp": "3.3.8",
		"clean-pkg-json": "^1.3.0",
		"execa": "^8.0.1",
		"fs-fixture": "^2.9.0",
		"is-fs-case-sensitive": "^2.0.0",
		"jsonc-parser": "^3.3.1",
		"lintroll": "^1.20.1",
		"manten": "^1.6.0",
		"pkgroll": "^2.6.1",
		"slash": "^5.1.0",
		"tsx": "^4.20.6",
		"type-fest": "^5.1.0",
		"typescript": "~5.9.3"
	}
}

